/**
 * C2 view-layer types.
 *
 * These MIRROR docs/CONTRACTS.md v0 as H-approved at 30d1ef6. They live in C2's
 * own namespace because `src/shared/**` is H-owned and no shared types package
 * exists yet. When H publishes shared types, replace these with re-exports.
 * Fields marked "view" are UI-derived; fields marked CR-C2-006 are proposed.
 */

export type Hex = `0x${string}`;
export type Address = `0x${string}`;

/** bytes32, server generated. Never generated by the frontend. */
export type VentureId = Hex;

export const SEPOLIA_CHAIN_ID = 11155111 as const;
export const WHITECHAIN_CHAIN_ID = 1874 as const;
/** ENSIP-11: 0x80000000 | 1874 */
export const WHITECHAIN_ENS_COIN_TYPE = 2147485522 as const;

/** CONTRACTS v0 read status enum. */
export type ReadStatus = "UNKNOWN" | "PENDING" | "VERIFIED" | "FAILED";

/** CONTRACTS v0 treasury verification — ACTIVE only after complete independent chain read-back. */
export type TreasuryStatus = "UNKNOWN" | "PENDING" | "ACTIVE" | "UNVERIFIED" | "FAILED";

/** CONTRACTS v0 payment lifecycle. */
export type PaymentStatus = "AWAITING_APPROVALS" | "READY" | "EXECUTED" | "FAILED";
/** CONTRACTS v0 relay submission lifecycle — SUBMITTED must never render as executed. */
export type RelayStatus = "RESERVED" | "UNKNOWN" | "SUBMITTED" | "EXECUTED" | "FAILED";

/** World environment a proof came from. `staging` = TESTED_IN_SIMULATOR, never production uniqueness. */
export type WorldEnvironment = "production" | "staging";

/** MASTER §3: exact evidence labels. */
export type EvidenceLabel = "HUMAN_VERIFIED" | "SIGNED" | "CHAIN_VERIFIED" | "SELF_REPORTED";

/** MASTER §11 claim classes. Every rendered fact resolves to one of these. */
export type ClaimClass =
  | "VERIFIED_ON_CHAIN"
  | "VERIFIED_OFF_CHAIN"
  | "TESTED_IN_SIMULATOR"
  | "IMPLEMENTED_NOT_TESTED"
  | "MOCK_ONLY"
  | "BLOCKED"
  | "CUT";

/** Where a piece of data came from. `DEV_MOCK` must always be rendered visibly. */
export type DataSource = "DEV_MOCK" | "API" | "CHAIN";

export type FounderSeat = {
  ventureId: VentureId;
  wallet: Address;
  founderLabel?: string;
  founderSubname: string;
  worldProofStatus: ReadStatus;
  onchainSeatStatus: ReadStatus;
  subnameStatus?: ReadStatus;
  attestationTxHash?: Hex;
  /** CR-C2-006 (proposed): which World environment verified this seat. Unknown → treated as unconfirmed. */
  worldEnvironment?: WorldEnvironment;
};

export type AgreementSignature = {
  signer: Address;
  /** Not returned by C1 (server keeps it); present only in DEV MOCK. */
  signature?: Hex;
  signedAt: string;
  /** version the signature was made over — must equal the agreement's version to count */
  version: number;
  docHash: Hex;
};

export type Agreement = {
  ventureId: VentureId;
  agreementId: Hex;
  version: number;
  /** Private. Only returned to current founders; never on the public page. */
  canonicalJson?: string;
  docHash: Hex;
  /** Signatures that count for THIS version + docHash. */
  signatures: AgreementSignature[];
  requiredSigners: Address[];
  complete: boolean;
  /** ENS `vestige.agreement` write status (VERIFIED only after receipt + read-back). */
  ensStatus: ReadStatus;
};

export type Treasury = {
  ventureId: VentureId;
  safeAddress: Address;
  chainId: typeof WHITECHAIN_CHAIN_ID;
  ownerAddresses: Address[];
  threshold: number;
  guardAddress: Address;
  registryAddress: Address;
  verificationStatus: TreasuryStatus;
  deploymentTxHash: Hex;
  /** Safe creation block (decimal string); public reader scans logs from here (CR-C2-004). */
  deploymentBlock?: string;
};

export type Payment = {
  paymentId: string;
  ventureId: VentureId;
  safeTxHash: Hex;
  recipient: Address;
  tokenAddress: Address;
  /** raw token units as a decimal string (never a float) */
  amountRaw: string;
  reason: string;
  signerWallets: Address[];
  status: PaymentStatus;
  relay?: { operationId: string; status: RelayStatus; txHash?: Hex; error?: string } | null;
  /** Exact Safe EIP-712 typed data from X's proposal; signed as-is (never rebuilt by C2 in live mode). */
  safeTypedData?: unknown;
  safeNonce?: string;
  executedTxHash?: Hex;
};

export type EvidenceKind =
  | "VENTURE_CREATED"
  | "FOUNDER_JOINED"
  | "ENS_REGISTERED"
  | "ENS_RECORD"
  | "FOUNDER_VERIFIED"
  | "SEAT_ATTESTED"
  | "DUPLICATE_REFUSED"
  | "AGREEMENT_VERSION"
  | "AGREEMENT_SIGNED"
  | "SAFE_DEPLOYED"
  | "DEPOSIT"
  | "PAYMENT_PROPOSED"
  | "PAYMENT_APPROVED"
  | "REJECTED_ATTEMPT"
  | "PAYMENT_EXECUTED";

export type Evidence = {
  id: string;
  ventureId: VentureId;
  kind: EvidenceKind;
  label: EvidenceLabel;
  status: ReadStatus;
  chainId?: number;
  txHash?: Hex;
  blockNumber?: string | number;
  confirmedAt?: string;
  source: DataSource;
  /** World evidence from the staging environment (CONTRACTS: separate qualifier, not a label). */
  qualifier?: "TESTED_IN_SIMULATOR";
};

/** Contract v0 `GET /api/identity/ventures/:id` — "founder seat + ENS + verification summaries". */
export type VentureDetail = {
  ventureId: VentureId;
  slug: string;
  displayName: string;
  ensName: string;
  ensStatus: ReadStatus;
  createdAt?: string;
  seats: FounderSeat[];
  agreement?: Agreement;
  /**
   * Public-list consent (CR-C2-001), exactly C1's `venture.listing` shape: listed only
   * while every current founder consents; any founder can withdraw. `null` = not reported.
   */
  listing?: { listed: boolean; consents: { wallet: Address; listed: boolean }[] } | null;
  source: DataSource;
};

/** Contract v0 `GET /api/treasury/ventures/:id` — "chain readback + pending payments". */
export type TreasuryState = {
  depositsStatus?: "UNKNOWN" | "PENDING" | "VERIFIED";
  treasury?: Treasury;
  /** raw USDT balance string from chain readback */
  balanceRaw?: string;
  tokenDecimals?: number;
  payments: Payment[];
  deposits: { from: Address; amountRaw: string; txHash: Hex; status: ReadStatus }[];
  /** Receipt-backed evidence from X's readback (e.g. the mined GS020 REJECTED_ATTEMPT). CR-C2-009. */
  evidence?: Evidence[];
  /** X operation log (RESERVED/UNKNOWN/SUBMITTED/EXECUTED/FAILED), as returned. */
  operations?: { operationId: string; status: RelayStatus; txHash?: Hex; blockNumber?: string; source?: string; error?: string | null }[];
  /** Venture-level World provenance computed by X from C1's stored environment. */
  worldSource?: "WORLD_PRODUCTION" | "TESTED_IN_SIMULATOR" | "UNKNOWN";
  /** Block the readback was pinned to. */
  readAtBlock?: string;
  /** False when the API does not report per-payment approvals (signerWallets). */
  approvalsReported?: boolean;
  source: DataSource;
};

/**
 * Contract v0 `GET /api/identity/public/:ensName` — OFFCHAIN human and agreement
 * evidence only. No authoritative treasury claims, no PII, no full nullifier.
 */
export type PublicOffchainEvidence = {
  ensName: string;
  ventureId: VentureId;
  humansVerified: number;
  founders: {
    founderSubname: string;
    wallet?: Address;
    worldProofStatus: ReadStatus;
    onchainSeatStatus?: ReadStatus;
    attestationTxHash?: Hex;
    verifiedAt?: string;
    /** CR-C2-006 (proposed). */
    worldEnvironment?: WorldEnvironment;
  }[];
  agreement?: {
    version: number;
    docHash: Hex;
    signaturesForCurrentVersion: number;
    requiredSignatures: number;
    complete?: boolean;
    ensRecordStatus?: ReadStatus;
  };
  evidence: Evidence[];
  source: DataSource;
};

/**
 * CR-C2-001 (approved): `GET /api/identity/ventures` — founder-consented, non-PII
 * cached summaries. `treasuryActive`/`funded` are null when unknown and are never
 * authoritative; the public page re-reads ENS + Whitechain.
 */
export type VentureSummary = {
  ventureId: VentureId;
  displayName: string;
  ensName: string;
  humansVerified: number;
  termsSigned: boolean;
  treasuryActive: boolean | null;
  funded: boolean | null;
  observedAt?: string;
  verificationStatus?: ReadStatus | TreasuryStatus;
  source: DataSource;
};
